mapper.select:
SELECT

FROM tl_article a
LEFT JOIN tl_user u ON u.id = a.author_id
LEFT JOIN tl_category c ON c.id = a.category_id


        AND (a.title LIKE CONCAT('%', #{q.keyword}, '%')
             OR a.summary LIKE CONCAT('%', #{q.keyword}, '%'))


        AND a.category_id = #{q.categoryId}


        AND a.status = #{q.status}


        AND EXISTS (
            SELECT 1 FROM tl_article_tag atg
            WHERE atg.article_id = a.id AND atg.tag_id = #{q.tagId}
        )


        AND a.id < #{q.cursor}


ORDER BY a.id DESC
LIMIT #{limit}
